interface CacheEntry { data: SeriesData; fetchedAt: number; }

export class EurostatDataError extends Error {
  constructor(message: string, readonly cause?: unknown) { super(message); this.name='EurostatDataError'; }
}

@Injectable({ providedIn: 'root' })
export class EurostatService {
  private readonly http = inject(HttpClient);
  private readonly cache = new Map<string, CacheEntry>();

  async getSeries(filters: SeriesFilters): Promise<SeriesData> {
    const key = `${filters.geo}:${filters.sex}`;
    const cached = this.cache.get(key);
    if (cached && Date.now() - cached.fetchedAt < CACHE_TTL_MS) return cached.data;
    const url = this.buildUrl(filters);
    let response: JsonStatDataset;
    try { response = await firstValueFrom(this.http.get<JsonStatDataset>(url)); }
    catch (error) { throw new EurostatDataError(this.message(filters, 'could not be loaded'), error); }
    const data = this.decode(response, filters);
    this.cache.set(key, { data, fetchedAt: Date.now() });
    return data;
  }

  private buildUrl(filters: SeriesFilters): string {
    const params = new URLSearchParams({ format:'JSON', lang:'EN', freq:'M', s_adj:'SA', age:'TOTAL', unit:'PC_ACT', sex:filters.sex, geo:filters.geo });
    return `${BASE_URL}?${params.toString()}`;
  }

  private decode(response: JsonStatDataset, filters: SeriesFilters): SeriesData {
    if (!response || response.class !== 'dataset') throw new EurostatDataError(this.message(filters, 'returned an unexpected dataset class'));
    if (!Array.isArray(response.id) || !Array.isArray(response.size)) throw ...
    if (response.id.length !== response.size.length) throw ...
    const timeDimension = response.id.indexOf('time');
