    const timeDimensionData = response.dimension?.['time'];
    const timeIndex = timeDimensionData?.category?.index;
    if (!timeIndex || typeof timeIndex !== 'object') throw ...
    if (!response.value || typeof response.value !== 'object') throw ...
    const strides = response.size.map((_, index) => response.size.slice(index + 1).reduce((product, size) => product * size, 1));
    const base = response.id.map(() => 0);
    const observations: Observation[] = [];
    for (const [period, position] of Object.entries(timeIndex)) {
