      base[timeDimension] = position;
      const flat = base.reduce((sum, categoryIndex, dimension) => sum + categoryIndex * strides[dimension], 0);
      const value = response.value[String(flat)];
      if (typeof value === 'number' && Number.isFinite(value)) observations.push({ period, rate: value });
    }
    if (observations.length === 0) throw new EurostatDataError(this.message(filters, 'returned no observations'));
    observations.sort((left,right)=>left.period.localeCompare(right.period));
    return { datasetLabel: response.label, source: response.source, updated: response.updated, observations };
  }

  private message(filters: SeriesFilters, detail: string): string {
    return `Eurostat series ${filters.geo}/${filters.sex} ${detail}.`;
  }
}
