import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import type { Observation, SeriesData, SeriesFilters } from '../series/saved-series.model';
import type { JsonStatDataset } from './eurostat.models';

const BASE_URL = 'https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/une_rt_m';
const CACHE_TTL_MS = 300_000;

interface CacheEntry {
  data: SeriesData;
  fetchedAt: number;
}

export class EurostatDataError extends Error {
  constructor(message: string, readonly cause?: unknown) {
    super(message);
    this.name = 'EurostatDataError';
  }
}

@Injectable({ providedIn: 'root' })
export class EurostatService {
  private readonly http = inject(HttpClient);
  private readonly cache = new Map<string, CacheEntry>();

  async getSeries(filters: SeriesFilters): Promise<SeriesData> {
    const cacheKey = `${filters.geo}:${filters.sex}`;
    const cached = this.cache.get(cacheKey);

    if (cached && Date.now() - cached.fetchedAt < CACHE_TTL_MS) {
      return cached.data;
    }

    let response: JsonStatDataset;

    try {
      response = await firstValueFrom(this.http.get<JsonStatDataset>(this.buildUrl(filters)));
    } catch (error) {
      throw new EurostatDataError(this.errorMessage(filters, 'could not be loaded'), error);
    }

    const data = this.decode(response, filters);
    this.cache.set(cacheKey, { data, fetchedAt: Date.now() });
    return data;
  }

  private buildUrl(filters: SeriesFilters): string {
    const params = new URLSearchParams({
      format: 'JSON',
      lang: 'EN',
      freq: 'M',
      s_adj: 'SA',
      age: 'TOTAL',
      unit: 'PC_ACT',
      sex: filters.sex,
      geo: filters.geo,
    });

    return `${BASE_URL}?${params.toString()}`;
  }

  private decode(response: JsonStatDataset, filters: SeriesFilters): SeriesData {
    if (!response || response.class !== 'dataset') {
      throw new EurostatDataError(this.errorMessage(filters, 'returned an unexpected dataset class'));
    }

    if (!Array.isArray(response.id) || !Array.isArray(response.size)) {
      throw new EurostatDataError(this.errorMessage(filters, 'returned an invalid dimension list'));
    }

    if (response.id.length !== response.size.length) {
      throw new EurostatDataError(this.errorMessage(filters, 'returned mismatched dimension sizes'));
    }

    if (
      typeof response.label !== 'string' ||
      typeof response.source !== 'string' ||
      typeof response.updated !== 'string'
    ) {
      throw new EurostatDataError(this.errorMessage(filters, 'returned incomplete metadata'));
    }

    const timeDimension = response.id.indexOf('time');
    if (timeDimension === -1) {
      throw new EurostatDataError(this.errorMessage(filters, 'returned no time dimension'));
    }

    const timeIndex = response.dimension?.['time']?.category?.index;
    if (!timeIndex || typeof timeIndex !== 'object') {
      throw new EurostatDataError(this.errorMessage(filters, 'returned no time category index'));
    }

    if (!response.value || typeof response.value !== 'object') {
      throw new EurostatDataError(this.errorMessage(filters, 'returned no value object'));
    }

    const strides = response.size.map((_, index) =>
      response.size.slice(index + 1).reduce((product, size) => product * size, 1),
    );
    const base = response.id.map(() => 0);
    const observations: Observation[] = [];

    for (const [period, position] of Object.entries(timeIndex)) {
      if (!Number.isInteger(position) || position < 0) {
        throw new EurostatDataError(this.errorMessage(filters, 'returned a malformed time index'));
      }

      base[timeDimension] = position;
      const flatIndex = base.reduce(
        (sum, categoryIndex, dimension) => sum + categoryIndex * strides[dimension],
        0,
      );
      const value = response.value[String(flatIndex)];

      if (typeof value === 'number' && Number.isFinite(value)) {
        observations.push({ period, rate: value });
      }
    }

    if (observations.length === 0) {
      throw new EurostatDataError(this.errorMessage(filters, 'returned no observations'));
    }

    observations.sort((left, right) => left.period.localeCompare(right.period));

    return {
      datasetLabel: response.label,
      source: response.source,
      updated: response.updated,
      observations,
    };
  }

  private errorMessage(filters: SeriesFilters, detail: string): string {
    return `Eurostat series ${filters.geo}/${filters.sex} ${detail}.`;
  }
}

