import { ChangeDetectionStrategy, Component, OnInit, inject, signal } from '@angular/core';
import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import {
  GEO_CODES,
  SEX_CODES,
  type GeoCode,
  type SavedSeriesInput,
  type SexCode,
} from '../../core/series/saved-series.model';
import { SeriesStoreService } from '../../core/series/series-store.service';
import { GEO_LABELS, SEX_LABELS } from '../../core/series/series-labels';

@Component({
  selector: 'app-series-form',
  imports: [ReactiveFormsModule, RouterLink],
  templateUrl: './series-form.html',
  styleUrl: './series-form.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class SeriesForm implements OnInit {
  private readonly formBuilder = inject(FormBuilder);
  private readonly route = inject(ActivatedRoute);
  private readonly router = inject(Router);
  private readonly store = inject(SeriesStoreService);

  readonly form = this.formBuilder.nonNullable.group({
    name: ['', [Validators.required, Validators.maxLength(80), Validators.pattern(/\S/)]],
    geo: ['PL' as GeoCode, Validators.required],
    sex: ['T' as SexCode, Validators.required],
    note: ['', [Validators.maxLength(2000)]],
  });

  readonly geoOptions = GEO_CODES;
  readonly sexOptions = SEX_CODES;
  readonly geoLabels = GEO_LABELS;
  readonly sexLabels = SEX_LABELS;

  readonly editing = signal(false);
  readonly notFound = signal(false);
  readonly submitError = signal<string | null>(null);
  readonly saving = signal(false);

  private seriesId: string | null = null;

  ngOnInit(): void {
    const id = this.route.snapshot.paramMap.get('id');
    if (!id) {
      return;
    }

    this.seriesId = id;
    this.editing.set(true);

    const record = this.store.series().find((item) => item.id === id);
    if (!record) {
      this.notFound.set(true);
      return;
    }

    this.form.setValue({
      name: record.name,
      geo: record.filters.geo,
      sex: record.filters.sex,
      note: record.note,
    });
  }

  submit(): void {
    this.submitError.set(null);

    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    this.saving.set(true);

    try {
      const value = this.form.getRawValue();
      const input: SavedSeriesInput = {
        name: value.name.trim(),
        note: value.note.trim(),
        filters: {
          geo: value.geo,
          sex: value.sex,
        },
      };
      const record = this.seriesId
        ? this.store.update(this.seriesId, input)
        : this.store.create(input);

      if (!record) {
        this.submitError.set('This saved series no longer exists.');
        return;
      }

      void this.router.navigate(['/series', record.id]);
    } catch (error) {
      this.submitError.set(error instanceof Error ? error.message : 'Could not save this series.');
    } finally {
      this.saving.set(false);
    }
  }

  cancel(): void {
    if (this.seriesId) {
      void this.router.navigate(['/series', this.seriesId]);
    } else {
      void this.router.navigate(['/series']);
    }
  }
}

@if (store.loadWarning(); as warning) {
  <div class="alert warning" role="status">{{ warning }}</div>
}

<div class="page-header">
  <div>
    <h1>{{ editing() ? 'Edit series' : 'New series' }}</h1>
    <p>
      Choose a country and sex. The app always requests monthly, seasonally adjusted, total-age
      unemployment rates from Eurostat.
    </p>
  </div>
  <div class="page-actions">
    <a class="button" routerLink="/series">Back to saved series</a>
  </div>
</div>

@if (notFound()) {
  <div class="alert error" role="alert">
    This saved series no longer exists.
    <a routerLink="/series">Return to saved series</a>.
  </div>
} @else {
  <form class="card stack" [formGroup]="form" (ngSubmit)="submit()" novalidate>
    <div class="form-grid">
      <div class="field full">
        <label for="series-name">Name</label>
        <input
          id="series-name"
          type="text"
          formControlName="name"
          maxlength="80"
          autocomplete="off"
          placeholder="e.g. Poland — total unemployment"
        />
        @if (form.controls.name.touched && form.controls.name.invalid) {
          <p class="field-error">Enter a name between 1 and 80 characters.</p>
        }
      </div>

      <div class="field">
        <label for="series-geo">Country</label>
        <select id="series-geo" formControlName="geo">
          @for (geo of geoOptions; track geo) {
            <option [value]="geo">{{ geoLabels[geo] }} ({{ geo }})</option>
          }
        </select>
      </div>

      <div class="field">
        <label for="series-sex">Sex</label>
        <select id="series-sex" formControlName="sex">
          @for (sex of sexOptions; track sex) {
            <option [value]="sex">{{ sexLabels[sex] }} ({{ sex }})</option>
          }
        </select>
      </div>

      <div class="field full">
        <label for="series-note">Note <span class="muted small">(optional)</span></label>
        <textarea
          id="series-note"
          formControlName="note"
          maxlength="2000"
          rows="5"
          placeholder="Why are you tracking this series?"
        ></textarea>
        <p class="small muted">{{ form.controls.note.value.length }} / 2,000 characters</p>
        @if (form.controls.note.touched && form.controls.note.invalid) {
          <p class="field-error">Keep the note to 2,000 characters or fewer.</p>
        }
      </div>
    </div>

    @if (submitError(); as error) {
      <div class="alert error" role="alert">{{ error }}</div>
    }

    <div class="form-actions">
      <button class="button primary" type="submit" [disabled]="saving()">
        {{ editing() ? 'Save changes' : 'Create series' }}
      </button>
      <button class="button ghost" type="button" (click)="cancel()">Cancel</button>
    </div>
  </form>
}

:host {
  display: block;
}

