import { ChangeDetectionStrategy, Component, OnInit, computed, inject, signal } from '@angular/core';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import { EurostatService } from '../../core/eurostat/eurostat.service';
import type { Observation, SavedSeries, SeriesData } from '../../core/series/saved-series.model';
import { SeriesStoreService } from '../../core/series/series-store.service';
import { GEO_LABELS, SEX_LABELS, formatTimestamp } from '../../core/series/series-labels';
import { RateChart } from '../../shared/rate-chart/rate-chart';

@Component({
  selector: 'app-series-detail',
  imports: [RouterLink, RateChart],
  templateUrl: './series-detail.html',
  styleUrl: './series-detail.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class SeriesDetail implements OnInit {
  private readonly route = inject(ActivatedRoute);
  private readonly router = inject(Router);
  private readonly eurostat = inject(EurostatService);
  readonly store = inject(SeriesStoreService);

  readonly series = signal<SavedSeries | null>(null);
  readonly data = signal<SeriesData | null>(null);
  readonly loading = signal(false);
  readonly error = signal<string | null>(null);
  readonly showAll = signal(false);
  readonly confirmingDelete = signal(false);
  readonly deleteError = signal<string | null>(null);

  readonly visibleObservations = computed(() => {
    const seriesData = this.data();
    if (!seriesData) {
      return [];
    }

    return this.showAll() ? seriesData.observations : seriesData.observations.slice(-24);
  });

  readonly tableObservations = computed(() => [...this.visibleObservations()].reverse());

  readonly hasMore = computed(() => (this.data()?.observations.length ?? 0) > 24);

  readonly latestObservation = computed<Observation | null>(
    () => this.data()?.observations.at(-1) ?? null,
  );

  readonly formatTimestamp = formatTimestamp;

  ngOnInit(): void {
    const id = this.route.snapshot.paramMap.get('id');
    if (!id) {
      this.error.set('Saved series not found.');
      return;
    }

    const record = this.store.series().find((item) => item.id === id);
    if (!record) {
      this.error.set('Saved series not found.');
      return;
    }

    this.series.set(record);
    void this.load();
  }

  async load(): Promise<void> {
    const record = this.series();
    if (!record) {
      return;
    }

    this.loading.set(true);
    this.error.set(null);

    try {
      const seriesData = await this.eurostat.getSeries(record.filters);
      this.data.set(seriesData);
    } catch (error) {
      this.data.set(null);
      this.error.set(
        error instanceof Error ? error.message : 'Could not load this Eurostat series.',
      );
    } finally {
      this.loading.set(false);
    }
  }

  toggleShowAll(): void {
    this.showAll.update((value) => !value);
  }

  deleteSeries(): void {
    const record = this.series();
    if (!record) {
      return;
    }

    this.deleteError.set(null);

    try {
      if (this.store.delete(record.id)) {
        void this.router.navigate(['/series']);
      } else {
        this.deleteError.set('This saved series no longer exists.');
      }
    } catch (error) {
      this.deleteError.set(
        error instanceof Error ? error.message : 'Could not delete this saved series.',
      );
    }
  }

  geoLabel(record: SavedSeries): string {
    return GEO_LABELS[record.filters.geo];
  }

  sexLabel(record: SavedSeries): string {
    return SEX_LABELS[record.filters.sex];
  }

  formatRate(rate: number): string {
    return rate.toFixed(1);
  }
}

@if (store.loadWarning(); as warning) {
  <div class="alert warning" role="status">{{ warning }}</div>
}

@if (series(); as record) {
  <div class="detail-header">
    <div class="detail-title-row">
      <div>
        <div class="series-meta">
          <span class="badge accent">{{ geoLabel(record) }}</span>
          <span class="badge">{{ sexLabel(record) }}</span>
          <span class="badge">{{ record.filters.geo }} · {{ record.filters.sex }}</span>
        </div>
        <h1>{{ record.name }}</h1>
      </div>
      <div class="page-actions">
        <a class="button" [routerLink]="['/series', record.id, 'edit']">Edit</a>
        <button class="button danger" type="button" (click)="confirmingDelete.set(true)">
          Delete
        </button>
      </div>
    </div>

    @if (record.note) {
      <p class="detail-note">{{ record.note }}</p>
    }

    <div class="source-line">
      <span>Created {{ formatTimestamp(record.createdAt) }}</span>
      <span>Updated {{ formatTimestamp(record.updatedAt) }}</span>
      <span>Monthly · seasonally adjusted · total age</span>
    </div>
  </div>

  @if (confirmingDelete()) {
    <div class="confirm-box" role="alert">
      <span>Delete “{{ record.name }}” from this browser?</span>
      <button class="button danger" type="button" (click)="deleteSeries()">Delete series</button>
      <button class="button ghost" type="button" (click)="confirmingDelete.set(false)">
        Cancel
      </button>
    </div>
  }

  @if (deleteError(); as message) {
    <div class="alert error" role="alert">{{ message }}</div>
  }

  @if (loading()) {
    <div class="card loading" role="status">
      <span class="spinner" aria-hidden="true"></span>
      Loading Eurostat observations…
    </div>
  } @else if (error(); as message) {
    <div class="alert error" role="alert">
      <p>{{ message }}</p>
      <button class="button" type="button" (click)="load()">Retry</button>
    </div>
  } @else if (data(); as seriesData) {
    <div class="stack">
      <section class="card stack chart-card">
        <div class="chart-header">
          <div>
            <h2>Unemployment rate</h2>
            <p class="muted small">
              Percent of active population, seasonally adjusted.
              @if (latestObservation(); as latest) {
                Latest {{ latest.period }}: {{ formatRate(latest.rate) }}%.
              }
            </p>
          </div>
          @if (hasMore()) {
            <button class="button" type="button" (click)="toggleShowAll()">
              {{ showAll() ? 'Show latest 24' : 'Show all observations' }}
            </button>
          }
        </div>
        <app-rate-chart [observations]="visibleObservations()" />
      </section>

      <section class="card stack">
        <div class="chart-header">
          <div>
            <h2>Observations</h2>
            <p class="muted small">
              Showing {{ visibleObservations().length }} of
              {{ seriesData.observations.length }} observations, newest first.
            </p>
          </div>
        </div>

        <div class="table-wrap">
          <table>
            <thead>
              <tr>
                <th scope="col">Period</th>
                <th class="numeric" scope="col">Rate (%)</th>
              </tr>
            </thead>
            <tbody>
              @for (observation of tableObservations(); track observation.period) {
                <tr>
                  <td>{{ observation.period }}</td>
                  <td class="numeric">{{ formatRate(observation.rate) }}</td>
                </tr>
              } @empty {
                <tr>
                  <td colspan="2">No observations returned.</td>
                </tr>
              }
            </tbody>
          </table>
        </div>

        <div class="source-line">
          <span>{{ seriesData.datasetLabel }}</span>
          <span>Source: {{ seriesData.source }}</span>
          <span>Eurostat updated {{ formatTimestamp(seriesData.updated) }}</span>
        </div>
      </section>
    </div>
  }
} @else if (error(); as message) {
  <div class="alert error" role="alert">
    <p>{{ message }}</p>
    <a routerLink="/series">Return to saved series</a>
  </div>
}

:host {
  display: block;
}

