import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { TestBed } from '@angular/core/testing';
import type { JsonStatDataset, JsonStatDimension } from './eurostat.models';
import { EurostatDataError, EurostatService } from './eurostat.service';

const API_URL = 'https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/une_rt_m';

function dimension(index: Record<string, number>): JsonStatDimension {
  return {
    label: 'Dimension',
    category: {
      index,
      label: Object.fromEntries(Object.keys(index).map((key) => [key, key])),
    },
  };
}

function dataset(): JsonStatDataset {
  return {
    version: '2.0',
    class: 'dataset',
    label: 'Unemployment by sex and age - monthly data',
    source: 'ESTAT',
    updated: '2026-10-21T11:00:00+0200',
    value: { '0': 3.9, '1': 4.2, '2': 4.0 },
    id: ['freq', 's_adj', 'age', 'unit', 'sex', 'geo', 'time'],
    size: [1, 1, 1, 1, 1, 1, 3],
    dimension: {
      freq: dimension({ M: 0 }),
      s_adj: dimension({ SA: 0 }),
      age: dimension({ TOTAL: 0 }),
      unit: dimension({ PC_ACT: 0 }),
      sex: dimension({ T: 0 }),
      geo: dimension({ PL: 0 }),
      time: dimension({ '2024-03': 0, '2024-01': 1, '2024-02': 2 }),
    },
  };
}

describe('EurostatService', () => {
  let service: EurostatService;
  let httpMock: HttpTestingController;

  beforeEach(() => {
    TestBed.configureTestingModule({
      providers: [provideHttpClient(), provideHttpClientTesting()],
    });

    service = TestBed.inject(EurostatService);
    httpMock = TestBed.inject(HttpTestingController);
  });

  afterEach(() => {
    httpMock.verify();
  });

  it('requests the expected filters and returns observations sorted by period', async () => {
    const promise = service.getSeries({ geo: 'PL', sex: 'T' });
    const request = httpMock.expectOne((candidate) => candidate.url === API_URL);

    expect(request.request.params.get('freq')).toBe('M');
    expect(request.request.params.get('s_adj')).toBe('SA');
    expect(request.request.params.get('age')).toBe('TOTAL');
    expect(request.request.params.get('unit')).toBe('PC_ACT');
    expect(request.request.params.get('geo')).toBe('PL');
    expect(request.request.params.get('sex')).toBe('T');

    request.flush(dataset());
    const result = await promise;

    expect(result.datasetLabel).toBe('Unemployment by sex and age - monthly data');
    expect(result.source).toBe('ESTAT');
    expect(result.observations).toEqual([
      { period: '2024-01', rate: 4.2 },
      { period: '2024-02', rate: 4.0 },
      { period: '2024-03', rate: 3.9 },
    ]);
  });

  it('caches a successful response for repeated filters', async () => {
    const first = service.getSeries({ geo: 'PL', sex: 'T' });
    httpMock.expectOne((candidate) => candidate.url === API_URL).flush(dataset());
    await first;

    const second = await service.getSeries({ geo: 'PL', sex: 'T' });

    expect(second.observations).toHaveLength(3);
    httpMock.expectNone((candidate) => candidate.url === API_URL);
  });

  it('rejects an unexpected dataset class', async () => {
    const promise = service.getSeries({ geo: 'DE', sex: 'M' });
    httpMock.expectOne((candidate) => candidate.url === API_URL).flush({ class: 'collection' });

    await expect(promise).rejects.toBeInstanceOf(EurostatDataError);
  });

  it('rejects a dataset with no observations', async () => {
    const empty = dataset();
    empty.value = {};
    empty.dimension['time'].category.index = {};

    const promise = service.getSeries({ geo: 'FR', sex: 'F' });
    httpMock.expectOne((candidate) => candidate.url === API_URL).flush(empty);

    await expect(promise).rejects.toBeInstanceOf(EurostatDataError);
  });

  it('wraps an HTTP failure in a EurostatDataError', async () => {
    const promise = service.getSeries({ geo: 'ES', sex: 'T' });
    httpMock
      .expectOne((candidate) => candidate.url === API_URL)
      .flush('server error', { status: 500, statusText: 'Server Error' });

    await expect(promise).rejects.toBeInstanceOf(EurostatDataError);
  });
});

import { TestBed } from '@angular/core/testing';
import type { SavedSeries } from './saved-series.model';
import {
  SeriesStorageError,
  SeriesStoreService,
  SeriesValidationError,
} from './series-store.service';

const STORAGE_KEY = 'eurostat-crud.saved-series.v1';
const CORRUPT_KEY = 'eurostat-crud.saved-series.v1.corrupt';

function record(overrides: Partial<SavedSeries> = {}): SavedSeries {
  return {
    id: 'series-1',
    name: 'Poland total',
    note: 'A note',
    filters: { geo: 'PL', sex: 'T' },
    createdAt: '2026-01-01T00:00:00.000Z',
    updatedAt: '2026-01-01T00:00:00.000Z',
    ...overrides,
  };
}

function createService(): SeriesStoreService {
  TestBed.configureTestingModule({});
  return TestBed.inject(SeriesStoreService);
}

describe('SeriesStoreService', () => {
  beforeEach(() => {
    localStorage.clear();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it('creates a trimmed record and persists the versioned envelope', () => {
    const service = createService();

    const created = service.create({
      name: '  Poland total  ',
      note: '  Watch this series  ',
      filters: { geo: 'PL', sex: 'T' },
    });

    expect(created.name).toBe('Poland total');
    expect(created.note).toBe('Watch this series');
    expect(created.id).toBeTruthy();
    expect(service.series()).toHaveLength(1);

    const stored = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? '{}') as {
      version: number;
      items: SavedSeries[];
    };
    expect(stored.version).toBe(1);
    expect(stored.items[0]?.name).toBe('Poland total');
  });

  it('updates a record in place while preserving its id and creation time', () => {
    const service = createService();
    const created = service.create({
      name: 'Original',
      note: '',
      filters: { geo: 'PL', sex: 'T' },
    });

    const updated = service.update(created.id, {
      name: 'Renamed',
      note: 'Updated note',
      filters: { geo: 'DE', sex: 'F' },
    });

    expect(updated?.id).toBe(created.id);
    expect(updated?.createdAt).toBe(created.createdAt);
    expect(updated?.name).toBe('Renamed');
    expect(updated?.filters).toEqual({ geo: 'DE', sex: 'F' });
    expect(service.series()).toHaveLength(1);
    expect(service.series()[0]?.name).toBe('Renamed');
  });

  it('deletes an existing record and reports missing ids', () => {
    const service = createService();
    const created = service.create({
      name: 'Delete me',
      note: '',
      filters: { geo: 'FR', sex: 'M' },
    });

    expect(service.delete(created.id)).toBe(true);
    expect(service.series()).toHaveLength(0);
    expect(service.delete('missing')).toBe(false);
  });

  it('loads valid records and drops invalid ones with a warning', () => {
    localStorage.setItem(
      STORAGE_KEY,
      JSON.stringify({
        version: 1,
        items: [
          record(),
          record({ id: 'bad-geo', filters: { geo: 'XX', sex: 'T' } }),
          record({ id: 'bad-name', name: ' ' }),
        ],
      }),
    );

    const service = createService();

    expect(service.series()).toHaveLength(1);
    expect(service.series()[0]?.id).toBe('series-1');
    expect(service.loadWarning()).toContain('invalid');
  });

  it('backs up corrupt JSON and starts empty with a warning', () => {
    localStorage.setItem(STORAGE_KEY, '{');

    const service = createService();

    expect(service.series()).toHaveLength(0);
    expect(service.loadWarning()).toContain('corrupt');
    expect(localStorage.getItem(CORRUPT_KEY)).toBe('{');
  });

  it('rejects invalid input before writing', () => {
    const service = createService();

    expect(() =>
      service.create({ name: '   ', note: '', filters: { geo: 'PL', sex: 'T' } }),
    ).toThrow(SeriesValidationError);

    expect(() =>
      service.create({ name: 'Valid', note: 'x'.repeat(2001), filters: { geo: 'PL', sex: 'T' } }),
    ).toThrow(SeriesValidationError);

    expect(() =>
      service.create({
        name: 'Valid',
        note: '',
        filters: { geo: 'XX' as 'PL', sex: 'T' },
      }),
    ).toThrow(SeriesValidationError);

    expect(service.series()).toHaveLength(0);
  });

  it('sorts records by most recently updated first', () => {
    vi.useFakeTimers();
    const service = createService();

    vi.setSystemTime(new Date('2026-01-01T00:00:00.000Z'));
    service.create({ name: 'Older', note: '', filters: { geo: 'PL', sex: 'T' } });

    vi.setSystemTime(new Date('2026-01-01T00:00:01.000Z'));
    service.create({ name: 'Newer', note: '', filters: { geo: 'DE', sex: 'M' } });

    expect(service.series().map((item) => item.name)).toEqual(['Newer', 'Older']);
  });
});

